from pathlib import Path
import json,csv,io,statistics,hashlib
ROOT=Path('/home/yangfp/teSpec-benchmark-tespec');BASE=ROOT/'benchmark/selection/paired-mutations';OUT=BASE/'performance/20261015-positive18';AUTO=OUT/'automatic-final'
raw=json.loads((AUTO/'raw-results.json').read_text());assert len(raw['runs'])==54
models=json.loads((OUT/'model-proof-results.json').read_text());assert len(models)==4 and all(x['status']=='KERNEL_CHECKED' for x in models)
first={x['source']:x for x in json.loads((OUT/'model-proof-results-attempt-1.json').read_text())};by_model={x['source']:x for x in models}
ids=list(dict.fromkeys(x['source'] for x in raw['runs']));rows=[]
def median(rs,key):return statistics.median(x[key]['wall_seconds'] for x in rs)
def peak(rs,key):return max(x[key]['resources']['max_process_rss_kib'] for x in rs)/1024
for ident in ids:
 rs=[x for x in raw['runs'] if x['source']==ident];assert len(rs)==3
 assert all(x['cn']['exit_code']==0 and x['qcp_auto']['native_result']=='success' and x['fulminate_pipeline']['exit_code']==0 and x['fulminate_test']['exit_code']==0 and all(s=='PASS' for s in x['tespec_auto']['statuses']) for x in rs)
 row={'program':ident,'test_input_count':rs[0]['input_count'],'cn_verify_s_median':median(rs,'cn'),'cn_peak_rss_mib':peak(rs,'cn'),'qcp_auto_s_median':median(rs,'qcp_auto'),'qcp_model_s_total':0,'qcp_compile_audit_s_total':0,'qcp_independent_kernel_s':0,'qcp_verify_stage_s_total':median(rs,'qcp_auto'),'qcp_peak_rss_mib':peak(rs,'qcp_auto'),'qcp_input_tokens':0,'qcp_cached_input_tokens':0,'qcp_output_tokens':0,'qcp_total_tokens':0,'qcp_model_attempts':0,'qcp_result':'VERIFIED_AUTOMATIC','fulminate_test_s_median':median(rs,'fulminate_test'),'fulminate_test_peak_rss_mib':peak(rs,'fulminate_test'),'fulminate_pipeline_s_median':median(rs,'fulminate_pipeline'),'fulminate_pipeline_peak_rss_mib':peak(rs,'fulminate_pipeline'),'tespec_test_s_median':median(rs,'tespec_auto'),'tespec_peak_rss_mib':peak(rs,'tespec_auto'),'tespec_input_tokens':0,'tespec_output_tokens':0,'tespec_total_tokens':0,'tespec_result':'PASS_ALL_FROZEN_INPUTS','configured_model':'gpt-6.1-sol'}
 if ident in by_model:
  m=by_model[ident];attempts=m['model'].get('previous_attempts',[])+[m['model']];compilation=first[ident]['compilation']+m['compilation']
  row['qcp_model_attempts']=len(attempts);row['qcp_model_s_total']=sum(a['wall_seconds'] for a in attempts);row['qcp_compile_audit_s_total']=sum(x['wall_seconds'] for x in compilation);row['qcp_independent_kernel_s']=m['kernel_replay']['wall_seconds']
  for attempt in attempts:
   assert attempt['requested_model']=='gpt-6.1-sol' and attempt['token_usage']
   for usage in attempt['token_usage']:
    for k in ['input_tokens','cached_input_tokens','output_tokens']:row['qcp_'+k]+=usage.get(k,0)
  row['qcp_total_tokens']=row['qcp_input_tokens']+row['qcp_output_tokens']
  row['qcp_verify_stage_s_total']+=row['qcp_model_s_total']+row['qcp_compile_audit_s_total']+row['qcp_independent_kernel_s']
  row['qcp_peak_rss_mib']=max([row['qcp_peak_rss_mib'],m['kernel_replay']['resources']['max_process_rss_kib']/1024]+[x['resources']['max_process_rss_kib']/1024 for x in compilation]+[x['resources']['max_process_peak_working_set_bytes']/1048576 for x in attempts])
  row['qcp_result']='VERIFIED_AUTOMATIC_PLUS_GPT61_MANUAL_KERNEL_CHECKED'
  assert (OUT/ident/'model/assumption-audit/stdout.log').read_text().strip()=='Closed under the global context'
 rows.append(row)
summary={'positive_programs':len(rows),'frozen_inputs':sum(x['test_input_count'] for x in rows),'automatic_repetitions_per_program':3,'automatic_subject_replays':len(raw['runs']),'finite_input_executions_per_tool_for_three_repetitions':sum(x['test_input_count'] for x in rows)*3,'model_assisted_qcp_programs':len(models),'actual_model_calls':sum(x['qcp_model_attempts'] for x in rows),'qcp_input_tokens':sum(x['qcp_input_tokens'] for x in rows),'qcp_cached_input_tokens':sum(x['qcp_cached_input_tokens'] for x in rows),'qcp_output_tokens':sum(x['qcp_output_tokens'] for x in rows),'qcp_total_tokens':sum(x['qcp_total_tokens'] for x in rows),'tespec_total_tokens':sum(x['tespec_total_tokens'] for x in rows),'all_measured_positive_results_accepted':True}
result={'schema':'tespec-positive-performance-summary/v1','summary':summary,'definitions':{'time':'Seconds. Automatic medians use three fresh processes and blocking monotonic timing. Model time, failed-attempt compilation, audits, and per-program independent coqchk use actual accumulated measured costs; no division of batch time.','qcp_verify_stage_s_total':'Median native QCP automatic time + actual model generation/repair time + all compilation/audit attempts + one independent per-program kernel replay. This is a sum of measured stages, not a median of three LLM runs or a continuously observed end-to-end wall interval. Queue/human orchestration gaps excluded.','memory':'MiB. Linux GNU time maximum process RSS, maximum across repetitions/stages; model client uses Windows peak working set. This is largest individual process peak, not sum of concurrent descendants, and excludes remote inference hardware.','fulminate':'Test-only execution and instrumentation+compilation+execution pipeline are reported separately; do not add them (pipeline already executes tests).','token':'Actual CLI turn.completed telemetry; input includes cached input, reasoning tokens are part of output and not added twice. Zero means model was not called, not missing telemetry. Failed attempts included.','scope':'CN/QCP universally verify selected functions; Fulminate/teSpec test only 85 frozen inputs. Sources with .broken lineage are corrected positive variants. No whole-program or exhaustive test claim.','model':'gpt-6.1-sol explicitly configured on every model command; CLI does not independently expose a server model fingerprint.','platform':'Validators run in Ubuntu-22.04 WSL on Windows; model client runs on Windows. C int is 32-bit; native Fulminate process uses host pointer ABI, teSpec/QCP target is 32-bit. These 18 cases do not perform pointer-width-sensitive arithmetic.','pilot':'Earlier raw-results.json is a pilot and proof-goal source. Final automatic metrics come exclusively from automatic-final/raw-results.json.'},'programs':rows}
(OUT/'summary.json').write_text(json.dumps(result,indent=2)+'\n')
csvbuf=io.StringIO();writer=csv.DictWriter(csvbuf,fieldnames=list(rows[0]));writer.writeheader();writer.writerows(rows);(OUT/'program-metrics.csv').write_text(csvbuf.getvalue())
def f(x):return f'{x:.6f}' if x<1 else f'{x:.3f}'
lines=['# 18 个正例的 CN / QCP / Fulminate / teSpec 实测结果','',f"共 {len(rows)} 个正例、{summary['frozen_inputs']} 组冻结输入。自动阶段逐程序串行运行 3 次，以下时间为中位数；模型补证及其检查记录实际全部尝试成本。四项 QCP 模型补证均完成，假设审计均为 Closed under the global context，且逐项通过独立 coqchk。",'',f"配置模型为 **gpt-6.1-sol**，共实际调用 {summary['actual_model_calls']} 次（每项 2 次，含失败和修复）。输入 {summary['qcp_input_tokens']:,} token，输出 {summary['qcp_output_tokens']:,} token，总计 **{summary['qcp_total_tokens']:,} token**；输入中的 {summary['qcp_cached_input_tokens']:,} token 为缓存命中，已包含在输入总数中。teSpec 本批全部由自动阶段 PASS，模型 token 为 **0**。",'', '单位：时间为秒，内存为 MiB。完整逐项字段见 program-metrics.csv，原始回执、日志和证明保留在同目录。','', '## CN 与 QCP','', 'QCP 总耗时为“自动验证中位数＋模型生成及修复＋所有编译/审计尝试＋该程序独立内核检查”的累计阶段成本。它不是 3 次模型运行的中位数，也不包含排队或人工调度间隔。自动证明不调用模型，token 为 0。','', '| 程序 | CN 秒 | CN 峰值 | QCP 自动秒 | QCP 总秒 | QCP 峰值 | QCP token |','|---|---:|---:|---:|---:|---:|---:|']
